.ag-charts-wrapper, .ag-charts-wrapper::after, .ag-charts-wrapper::before, .ag-charts-wrapper *, .ag-charts-wrapper ::after, .ag-charts-wrapper ::before { box-sizing: border-box; }
.ag-charts-wrapper { --align-items: center; --justify-content: center; position: relative; user-select: none; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); }
.ag-charts-wrapper--cursor-locked .ag-charts-proxy-elem { cursor: inherit !important; }
.ag-charts-wrapper--safe-horizontal { --justify-content: flex-start; }
.ag-charts-wrapper--safe-vertical { --align-items: flex-start; }
.ag-charts-tab-guard { width: 0px; height: 0px; position: absolute; pointer-events: none; }
.ag-charts-canvas-background { position: absolute; }
.ag-charts-canvas-center { position: absolute; touch-action: auto; pointer-events: auto; display: flex; align-items: var(--align-items); justify-content: var(--justify-content); }
.ag-charts-canvas-container, .ag-charts-canvas { position: relative; user-select: none; }
.ag-charts-canvas-container > *, .ag-charts-canvas > * { pointer-events: none; }
.ag-charts-canvas canvas { display: block; }
.ag-charts-series-area { outline: none; pointer-events: auto; position: absolute; }
.ag-charts-swapchain { top: 0px; left: 0px; outline: none; opacity: 0; pointer-events: none; position: absolute; width: 100%; height: 100%; }
.ag-charts-swapchain:focus-visible { opacity: 1; }
.ag-charts-canvas-proxy, .ag-charts-canvas-overlay { position: absolute; inset: 0px; pointer-events: none; user-select: none; }
.ag-charts-canvas-overlay > * { position: absolute; pointer-events: auto; }
.ag-charts-canvas-overlay > [role="presentation"] { left: 0px; }
.ag-charts-style-sensors { visibility: hidden; position: absolute; }
