.snap-html { width: 100%; height: 100%; }
.snap-html[data-bs-theme="dark"] { background-color: rgb(14, 14, 16); }
#initial-loader { position: fixed; inset: 0px; display: flex; align-items: center; justify-content: center; z-index: 9999; }
.snap-html[data-bs-theme="light"] #initial-loader { background-color: rgb(245, 248, 251); }
.snap-html[data-bs-theme="dark"] #initial-loader { background-color: rgb(14, 14, 16); }
.loader-content { display: flex; flex-direction: column; align-items: center; gap: 40px; }
@keyframes progress { 
  0% { transform: translateX(-100%); }
  50% { transform: translateX(0%); }
  100% { transform: translateX(100%); }
}
.loader-logo-wrapper { width: 120px; height: 120px; }
.loader-logo { width: 100%; height: 100%; }
.loader-progress { width: 150px; height: 6px; border-radius: 3px; overflow: hidden; }
.snap-html[data-bs-theme="light"] .loader-progress { background-color: rgb(220, 220, 222); }
.snap-html[data-bs-theme="dark"] .loader-progress { background-color: rgb(58, 58, 63); }
.loader-progress-bar { height: 100%; width: 50%; background: linear-gradient(90deg, rgb(240, 69, 39) 0%, rgb(255, 144, 102) 50%, rgb(240, 188, 116) 100%); border-radius: 3px; animation: 2s cubic-bezier(0.4, 0, 0.2, 1) 0s infinite normal none running progress; }





.font-details-accent { font-family: "Currency Glyphs", Nunito, Arial, Helvetica, sans-serif !important; font-weight: 400 !important; font-size: 12px !important; line-height: 16px !important; }
.font-main { font-family: "Currency Glyphs", Nunito, Arial, Helvetica, sans-serif !important; font-weight: 400 !important; font-size: 14px !important; line-height: 18px !important; }
.font-accent { font-family: "Currency Glyphs", Nunito, Arial, Helvetica, sans-serif !important; font-weight: 400 !important; font-size: 16px !important; line-height: 24px !important; }

.font-block-heading { font-family: "Currency Glyphs", Nunito, Arial, Helvetica, sans-serif !important; font-weight: 400 !important; font-size: 20px !important; line-height: 28px !important; }

.font-accent-bold { font-family: "Currency Glyphs", Nunito, Arial, Helvetica, sans-serif !important; font-weight: 700 !important; font-size: 16px !important; line-height: 24px !important; }

.font-block-heading-bold { font-family: "Currency Glyphs", Nunito, Arial, Helvetica, sans-serif !important; font-weight: 700 !important; font-size: 20px !important; line-height: 28px !important; }

.font-link { border-bottom: 1px dashed rgba(38, 43, 64, 0.3); }
.font-link:hover { border-bottom: 1px dashed var(--primary); }
.icon-refresh { padding: 0px 1.3rem; font-size: 21px; }
.icon-refresh__anim { animation: 1s linear 0s infinite reverse none running refresh; }
@keyframes refresh { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(359deg); }
